# Source-bound R rendering of original Palantir fields and author-R-gam trends.
load_case<-function(P){W<-file.path(P,'work/2026-10-28-batch-six/single-cell');.libPaths(c(file.path(W,'Rlib'),.libPaths()));suppressPackageStartupMessages({library(ggplot2);library(patchwork);library(grid)});invisible(W)}
make_native<-function(P){W<-file.path(P,'work/2026-10-28-batch-six/single-cell');O<-file.path(W,'results/plot_data');cells<-read.csv(file.path(O,'cells.csv'),check.names=FALSE);d<-read.csv(file.path(O,'publication_selected_trends.csv'));branch_order<-c('CLP','Ery','Mega','Mono','cDC','pDC');branch_colors<-c(CLP='#C6AB84',Ery='#639C8D',Mega='#B78357',Mono='#416E8C',cDC='#6C99AD',pDC='#9DBFC6');cluster_colors<-c('0'='#A0809C','1'='#BEA8BD','2'='#A7BAA2','3'='#416E8C','4'='#9698AD','5'='#C6AB84','6'='#416E8C','7'='#9DBFC6','8'='#639C8D','9'='#B78357');ramp<-c('#514A78','#B47F98','#E6C99B')
 base<-theme_classic(base_family='Arial',base_size=7)+theme(text=element_text(family='Arial',size=7),plot.title=element_text(size=8,hjust=.5,margin=margin(b=2,unit='mm')),plot.tag=element_text(size=9,face='bold'),plot.tag.position=c(0,1),axis.text=element_text(size=6.5,color='#333B40'),axis.title=element_text(size=7),axis.line=element_line(linewidth=.25,color='#333B40'),axis.ticks=element_line(linewidth=.2,color='#333B40'),axis.ticks.length=unit(1,'mm'),panel.grid=element_blank(),plot.background=element_rect(fill='white',colour=NA),panel.background=element_rect(fill='white',colour=NA),legend.text=element_text(size=6.5),legend.title=element_blank(),legend.background=element_rect(fill='white',colour=NA),legend.key=element_rect(fill='white',colour=NA),plot.margin=margin(3,3,3,3,'mm'))
 embtheme<-base+theme(axis.line=element_blank(),axis.ticks=element_blank(),axis.text=element_blank(),axis.title=element_blank(),legend.position='right',legend.margin=margin(0,0,0,0,'mm'))
 spatial<-coord_fixed(xlim=c(-35,30),ylim=c(-34,31),expand=FALSE,clip='off')
 labels<-data.frame(label=c('HSC','Mono','CLP','pDC','cDC','Ery','Mega'),x=c(17,-30,-7,-32,-27,5,25),y=c(25,18,28,-4.5,-15,-32,-10),color=c('#A0809C','#416E8C','#C6AB84','#9DBFC6','#6C99AD','#639C8D','#B78357'))
 pb<-ggplot(cells,aes(tsne_x,tsne_y,color=factor(cluster_id)))+geom_point(size=.42,shape=16,alpha=.9,stroke=0)+scale_color_manual(values=cluster_colors,guide='none')+spatial+embtheme+labs(title='Cell type composition',tag='b')
 for(i in seq_len(nrow(labels)))pb<-pb+annotate('text',x=labels$x[i],y=labels$y[i],label=labels$label[i],color=labels$color[i],family='Arial',size=6.5/ggplot2::.pt)
 colguide<-guide_colourbar(title=NULL,barwidth=unit(1.6,'mm'),barheight=unit(17,'mm'),ticks=FALSE,frame.colour=NA)
 pc<-ggplot(cells,aes(tsne_x,tsne_y,color=pseudotime))+geom_point(size=.42,shape=16,alpha=.95,stroke=0)+scale_color_gradientn(colours=ramp,limits=range(cells$pseudotime),breaks=c(0,.5,1),guide=colguide)+spatial+embtheme+labs(title='Pseudotime',tag='c')
 pd<-ggplot(cells,aes(tsne_x,tsne_y,color=differentiation_potential))+geom_point(size=.42,shape=16,alpha=.95,stroke=0)+scale_color_gradientn(colours=ramp,limits=range(cells$differentiation_potential),breaks=c(0,.7,1.4),guide=colguide)+spatial+embtheme+labs(title='Differentiation potential',tag='d')
 gg<-c('CD34','CD79B','GATA1','IRF8','MPO','CD41');plots<-lapply(seq_along(gg),function(i){z<-d[d$gene_label==gg[i],];p<-ggplot(z,aes(pseudotime,fit,color=branch,fill=branch,group=branch))+geom_ribbon(aes(ymin=lower,ymax=upper),alpha=.12,colour=NA,show.legend=FALSE)+geom_line(linewidth=.38,alpha=1)+scale_color_manual(values=branch_colors,limits=branch_order,name=NULL)+scale_fill_manual(values=branch_colors,limits=branch_order,guide='none')+scale_x_continuous(limits=c(0,1),breaks=c(0,.2,.4,.6,.8,1),expand=expansion(mult=0))+scale_y_continuous(limits=c(-.2,1.2),breaks=c(0,.5,1),expand=expansion(mult=0))+base+labs(title=gg[i],x=if(i>3)'Palantir pseudotime'else NULL,y=if(i%%3==1)'Normalized expression'else NULL,tag=if(i==1)'f'else NULL)+theme(plot.title=element_text(face='italic',size=8,hjust=.5),legend.position='bottom',legend.key.width=unit(5,'mm'),legend.key.height=unit(2,'mm'));if(i%%3!=1)p<-p+theme(axis.text.y=element_blank(),axis.ticks.y=element_blank());if(i!=6)p<-p+guides(colour='none');p})
 top<-pb+pc+pd+plot_layout(ncol=3,widths=c(1,1,1),guides='keep');bottom<-wrap_plots(plots,ncol=3,guides='collect')&theme(legend.position='bottom');all<-top/bottom+plot_layout(heights=c(1.08,2.05))
 g<-patchwork::patchworkGrob(all)
 list(grob=g,plots=list(b=pb,c=pc,d=pd,f=plots),cells=cells,trends=d,branch_colors=branch_colors,cluster_colors=cluster_colors,ramp=ramp)
}
